function blankAdditional(s,d){const all=localFieldsFor(d.type);for(const [role,label] of docPartyRoles(d.type)){const k=docPartyKeys(role,d.type);for(const [field,key] of Object.entries(k)){if(field==='name')continue;all.push([key,label+': '+({inn:'ИНН',kpp:'КПП',ogrn:'ОГРН / ОГРНИП',address:'Адрес',postalAddress:'Почтовый адрес',phone:'Телефон',email:'Электронная почта',sign:'Подписант',basis:'Основание полномочий',bank:'Банк',bik:'БИК',account:'Расчётный счёт',correspondent:'Корреспондентский счёт',legacy:'Ранее сохранённые реквизиты'}[field]||field)]);}}
 const seen=new Set();const extra=all.filter(([key])=>!seen.has(key)&&seen.add(key)&&!s.used.has(key)&&String(d[key]??'').trim());if(extra.length){s.title('Дополнительные сведения');for(const [key,label] of extra)s.ruled(label,d[key],[key],9);}}
function docBuildScene(input){const d=docNormalizeParties(input),s=blankScene(d.type);switch(d.type){case 'tn':blankTransport(s,d);break;case 'ttn':blankCommodity(s,d,true);break;case 'torg12':blankCommodity(s,d,false);break;case 'invoice':blankInvoice(s,d);break;case 'act':blankAct(s,d);break;case 'vat':blankTax(s,d,false);break;case 'upd':blankTax(s,d,true);break;case 'waybill':blankWaybill(s,d);break;case 'reconcile':blankReconcile(s,d);break;case 'order':blankContract(s,d,true);break;default:blankContract(s,d,false);}
 blankAdditional(s,d);s.pages.forEach((page,i)=>{page.ops.push({kind:'line',x:9,y:s.h-11,x2:s.w-9,y2:s.h-11});page.ops.push({kind:'text',text:DOC_BLANK_BRAND,x:9,y:s.h-6,size:6.3,align:'left'},{kind:'text',text:(i+1)+' / '+s.pages.length,x:s.w-9,y:s.h-6,size:6.3,align:'right'});});return s;}
function docSceneHTML(scene){const escAttr=esc,font=window.docPdfFont?'@font-face{font-family:BlankFont;src:url(data:font/ttf;base64,'+window.docPdfFont+')}':'';const pages=scene.pages.map((page,i)=>'<section class="blank-page" data-blank-page="'+i+'" style="aspect-ratio:'+scene.w+'/'+scene.h+'"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 '+scene.w+' '+scene.h+'" role="img" aria-label="Страница '+(i+1)+' документа">'+page.ops.map(op=>op.kind==='text'?'<text x="'+op.x+'" y="'+op.y+'" font-size="'+(op.size*25.4/72)+'" text-anchor="'+({left:'start',center:'middle',right:'end'}[op.align]||'start')+'">'+esc(op.text)+'</text>':op.kind==='line'?'<line x1="'+op.x+'" y1="'+op.y+'" x2="'+op.x2+'" y2="'+op.y2+'"/>':'<rect x="'+op.x+'" y="'+op.y+'" width="'+op.w+'" height="'+op.h+'"/>').join('')+page.marks.map(mark=>'<rect class="field-target" data-fields="'+escAttr('|'+mark.keys.join('|')+'|')+'" x="'+mark.x+'" y="'+mark.y+'" width="'+mark.w+'" height="'+mark.h+'"/>').join('')+'</svg></section>').join('');return '<!doctype html><html lang="ru"><head><meta charset="UTF-8"><title>'+esc(docLabel(scene.type))+'</title><style>'+font+'*{box-sizing:border-box}html{scroll-behavior:auto}body{margin:0;background:#e5e9ed;padding:12px}.blank-page{width:100%;max-width:'+scene.w+'mm;background:white;margin:0 auto 15px;box-shadow:0 2px 12px #0002;break-after:page;page-break-after:always}.blank-page:last-child{break-after:auto;page-break-after:auto}svg{display:block;width:100%;height:100%;font-family:BlankFont,"DejaVu Sans",Arial,sans-serif}svg text{fill:#111;stroke:none}svg line,svg rect{fill:none;stroke:#111;stroke-width:.2}.field-target{fill:transparent;stroke:none;cursor:pointer}.field-target.active{fill:#00a99b;fill-opacity:.16;stroke:#008f83;stroke-width:.5}svg text{pointer-events:none}@page{size:A4 '+(scene.w>scene.h?'landscape':'portrait')+';margin:0}@media print{body{padding:0;background:white}.blank-page{width:'+scene.w+'mm;height:'+scene.h+'mm;max-width:none;margin:0;box-shadow:none}.field-target{display:none!important}}</style></head><body>'+pages+'</body></html>';}

let docActiveField='',docFocusScroll=true;
function docInputKey(el){if(!el)return '';if(el.dataset.docField)return el.dataset.docField;if(el.dataset.itemField)return 'item:'+el.closest('[data-item-index]').dataset.itemIndex+':'+el.dataset.itemField;if(el.dataset.itemExtra)return 'item:'+el.closest('[data-item-extra-index]').dataset.itemExtraIndex+':'+el.dataset.itemExtra;if(el.dataset.operationField)return 'operation:'+el.closest('[data-operation-index]').dataset.operationIndex+':'+el.dataset.operationField;return '';}
function docHighlightField(key,scroll=true){const frame=document.getElementById('doc-preview'),inner=frame?.contentDocument;if(!inner)return;const targets=[...inner.querySelectorAll('[data-fields]')];targets.forEach(el=>el.classList.toggle('active',!!key&&el.dataset.fields.includes('|'+key+'|')));const first=targets.find(el=>el.classList.contains('active'));if(first&&scroll){const bounds=first.getBoundingClientRect();frame.contentWindow.scrollTo({top:Math.max(0,frame.contentWindow.scrollY+bounds.top-frame.clientHeight*.3),behavior:'auto'});}const hint=document.getElementById('doc-field-hint');if(hint)hint.textContent=key?(first?'Подсвечена строка документа для выбранного поля':'Поле отобразится в дополнительных сведениях после заполнения'):'Выберите поле слева — нужная строка бланка подсветится';}
function docFocusBlankField(keys){const form=document.getElementById('local-document-form');if(!form)return;for(const key of keys){let el;if(key.startsWith('item:')){const [,i,k]=key.split(':');el=form.querySelector('[data-item-index="'+i+'"] [data-item-field="'+k+'"]')||form.querySelector('[data-item-extra-index="'+i+'"] [data-item-extra="'+k+'"]');}else if(key.startsWith('operation:')){const [,i,k]=key.split(':');el=form.querySelector('[data-operation-index="'+i+'"] [data-operation-field="'+k+'"]');}else el=form.elements.namedItem(key);if(el&&el.focus){const panel=el.closest('[role="tabpanel"]');if(panel)docSwitchStep(Number(panel.id.replace('doc-step-','')));for(const details of [...el.closest('form').querySelectorAll('details')])if(details.contains(el))details.open=true;el.focus();el.scrollIntoView({block:'center',behavior:'smooth'});return;}}}
document.addEventListener('focusin',e=>{if(!e.target.closest('#local-document-form'))return;const key=docInputKey(e.target);if(key){docActiveField=key;docHighlightField(key,true);}});
